# ==============================================================================# IOTEC MISSION CONTROL# 006_CONFIGURATION_ENGINE.py# ==============================================================================import jsonfrom pathlib import PathROOT = Path(__file__).resolve().parentCONFIG = ROOT / "MISSION_CONTROL" / "config"CONFIG.mkdir(parents=True, exist_ok=True)SYSTEM = {    "system_name": "IOTEC Mission Control",    "version": "1.0.0",    "language": "pt-BR",    "theme": "dark",    "database": "sqlite",    "event_bus": True,    "logs": True,    "debug": False,    "timezone": "America/Fortaleza"}MAESTRO = {    "enabled": True,    "voice": False,    "mission_mode": True,    "auto_analysis": True,    "confidence_limit": 0.80}MISSION = {    "auto_archive": False,    "history_limit": 100000,    "default_priority": "NORMAL",    "allow_parallel": True}FILES = {    "system.json": SYSTEM,    "maestro.json": MAESTRO,    "mission.json": MISSION}for file, content in FILES.items():    with open(CONFIG / file, "w", encoding="utf-8") as f:        json.dump(content, f, indent=4, ensure_ascii=False)    print(f"[OK] {file}")print("=" * 80)print("CONFIGURATION ENGINE ONLINE")print("=" * 80)

